mapper.sql:
(SELECT PPS.PAY_SCHEDULE_NO
   FROM PA_PAY_SCHEDULE PPS
  WHERE PPS.CPNY_ID = #{cpnyId, jdbcType=VARCHAR}
    AND TO_CHAR(PPS.PAY_DATE, 'DD-MM-YYYY') = #{payDate, jdbcType=VARCHAR}
    AND PPS.SALARY_DISTIN_NO = #{salaryDistinNo, jdbcType=VARCHAR}
    AND PPS.ACTIVITY = 1
    AND ROWNUM = 1)

(SELECT PPS.PAY_SCHEDULE_NO
   FROM PA_PAY_SCHEDULE PPS
  WHERE PPS.CPNY_ID = #{cpnyId, jdbcType=VARCHAR}
    AND TO_CHAR(PPS.PAY_DATE, 'DD-MM-YYYY') = #{payDatePro, jdbcType=VARCHAR}
    AND PPS.SALARY_DISTIN_NO = #{salaryDistinNo, jdbcType=VARCHAR}
    AND PPS.ACTIVITY = 1
    AND ROWNUM = 1)

sql.if:
AND EXISTS (SELECT B1.DEPTID
              FROM HR_DEPARTMENT B1
             WHERE B1.DEPTNO = PA.DEPTNO
               AND B1.CPNY_ID = #{cpnyId, jdbcType=VARCHAR}
             START WITH B1.DEPTNO = #{deptNo, jdbcType=VARCHAR}
           CONNECT BY PRIOR B1.DEPTNO = B1.PARENT_DEPT_NO)

mapper.select:
SELECT HE.PERSON_ID, HE.EMPID, HE.LOCAL_NAME, HE.DEPTNO, GET_DEPT_NAME(HE.DEPTNO, #{lang, jdbcType=VARCHAR}) AS DEPT_NAME, GET_GLOBAL_NAME(HE.POST_FAMILY, #{lang, jdbcType=VARCHAR}) AS POST_FAMILY_NAME, GET_GLOBAL_NAME(HE.POST_GRADE_NO, #{lang, jdbcType=VARCHAR}) AS POST_GRADE_NAME, GET_GLOBAL_NAME(HE.POSITION_NO, #{lang, jdbcType=VARCHAR}) AS POSITION_NAME, GET_GLOBAL_NAME(HE.DUTY_NO, #{lang, jdbcType=VARCHAR}) AS DUTY_NAME, GET_GLOBAL_NAME(HE.MAIN_BUSINESS, #{lang, jdbcType=VARCHAR}) AS MAIN_BUSINESS, GET_GLOBAL_NAME(HE.EMP_TYPE_CODE, #{lang, jdbcType=VARCHAR}) AS EMP_TYPE_NAME, GET_GLOBAL_NAME(HE.EMP_OFFICE, #{lang, jdbcType=VARCHAR}) AS EMP_OFFICE_NAME, TO_CHAR(HE.DATE_STARTED, 'DD/MM/YYYY') AS DATE_STARTED, TO_CHAR(HE.DATE_LEFT, 'DD/MM/YYYY') AS DATE_LEFT FROM HR_EMPLOYEE HE WHERE HE.CPNY_ID = #{cpnyId, jdbcType=VARCHAR} AND HE.PERSON_ID IN
#{pid, jdbcType=VARCHAR}
ORDER BY HE.EMPID

