mapper.select:
SELECT , GET_GLOBAL_NAME(PA.EMP_TYPE_CODE, #{lang, jdbcType=VARCHAR}) AS EMP_TYPE_NAME, GET_GLOBAL_NAME(PA.EMP_OFFICE, #{lang, jdbcType=VARCHAR}) AS EMP_OFFICE_NAME, TO_CHAR(PA.DATE_STARTED, 'DD/MM/YYYY') AS DATE_STARTED, TO_CHAR(PA.END_PROBATION_DATE, 'DD/MM/YYYY') AS END_PROBATION_DATE, TO_CHAR(PA.DATE_LEFT, 'DD/MM/YYYY') AS DATE_LEFT, PDIT.ITEM_NO, GET_GLOBAL_NAME(PDIT.ITEM_NO, #{lang, jdbcType=VARCHAR}) AS ITEM_NAME, PDIT.MONTH_PRO, PDIT.MONTH_NOW, TO_CHAR(NVL(PDIT.FORMULAR_VALUE, PDIT.MONTH_NOW)) AS FORMULAR_VALUE FROM PA_MONTH_DIF_ITEM_TEMP PDIT, PA_SUMMARY_HTSV PA WHERE PDIT.CREATED_BY = #{adminID, jdbcType=VARCHAR} AND PA.PERSON_ID = PDIT.PERSON_ID AND PA.PAY_SCHEDULE_NO = (SELECT PPS.PAY_SCHEDULE_NO FROM PA_PAY_SCHEDULE PPS WHERE TO_CHAR(PPS.PAY_DATE, 'DD-MM-YYYY') = #{payDate, jdbcType=VARCHAR} AND PPS.CPNY_ID = #{cpnyId, jdbcType=VARCHAR}
AND PPS.SALARY_DISTIN_NO = #{salaryDistinNo, jdbcType=VARCHAR}
AND ROWNUM = 1) AND PDIT.ITEM_TYPE = #{itemType, jdbcType=NUMERIC} AND PDIT.PAGE_TYPE = #{pageType, jdbcType=VARCHAR}
AND PDIT.MONTH_DIF = #{monthDif, jdbcType=VARCHAR}
AND PDIT.MONTH_DIF IN ('0', '1', '2', '4')
AND PDIT.ITEM_ID = #{itemId, jdbcType=VARCHAR}
AND PDIT.MONTH_NOW <> '0'
AND PDIT.MONTH_PRO <> '0'
AND PDIT.MONTH_NOW > PDIT.MONTH_PRO
AND PDIT.MONTH_NOW < PDIT.MONTH_PRO
AND PDIT.PERSON_ID NOT IN (SELECT PDIT2.PERSON_ID FROM PA_MONTH_DIF_ITEM_TEMP PDIT2 WHERE PDIT2.ITEM_ID = PDIT.ITEM_ID AND PDIT2.PAGE_TYPE = #{pageType, jdbcType=VARCHAR} AND PDIT2.CREATED_BY = #{adminID, jdbcType=VARCHAR} AND PDIT2.MONTH_PRO <> '0')
AND PDIT.PERSON_ID NOT IN (SELECT PDIT2.PERSON_ID FROM PA_MONTH_DIF_ITEM_TEMP PDIT2 WHERE PDIT2.ITEM_ID = PDIT.ITEM_ID AND PDIT2.PAGE_TYPE = #{pageType, jdbcType=VARCHAR} AND PDIT2.CREATED_BY = #{adminID, jdbcType=VARCHAR} AND PDIT2.MONTH_NOW <> '0')
ORDER BY PA.DATE_STARTED, PA.EMPID

SELECT HRE.PERSON_ID, HRE.EMPID, HRE.LOCAL_NAME, TO_CHAR(TO_DATE(AD.AR_DATE_STR, 'YYYY/MM/DD'), 'DD/MM/YYYY') AS AR_DATE, TO_CHAR(AD.FROM_TIME, 'DD/MM/YYYY HH24:MI') AS FROM_TIME, TO_CHAR(AD.TO_TIME, 'DD/MM/YYYY HH24:MI') AS TO_TIME, GET_GLOBAL_NAME(AD.SHIFT_NO, #{lang, jdbcType=VARCHAR}) AS SHIFT_NAME, GET_GLOBAL_NAME(AD.ITEM_NO, #{lang, jdbcType=VARCHAR}) AS ITEM_NAME, AD.QUANTITY FROM AR_DETAIL_HTSV AD, HR_EMPLOYEE HRE WHERE AD.PERSON_ID = HRE.PERSON_ID AND AD.ACTIVITY = 1 AND AD.ITEM_NO IN (90000295, 90000296, 90000297, 90000298, 90000299, 90000300, 90000301) AND AD.PERSON_ID = #{personId, jdbcType=VARCHAR}
AND AD.AR_DATE_STR BETWEEN #{arStartDate, jdbcType=VARCHAR} AND #{arEndDate, jdbcType=VARCHAR}
ORDER BY AD.AR_DATE_STR, AD.ITEM_NO
